import{_ as e,o as a,c as r,a2 as o}from"./chunks/framework.C2TvIV46.js";const p=JSON.parse('{"title":"設定","description":"","frontmatter":{},"headers":[],"relativePath":"ja/megacrow/settings.md","filePath":"ja/megacrow/settings.md"}'),l={name:"ja/megacrow/settings.md"};function i(d,t,h,n,s,c){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="設定" tabindex="-1">設定 <a class="header-anchor" href="#設定" aria-label="Permalink to &quot;設定&quot;">​</a></h1><p>ツールバーから <strong>Settings</strong> を開きます。オプションは <strong>Compiler</strong> と <strong>Editor</strong> に分かれています。変更はすぐに反映され、セッション間で保持されます。</p><h2 id="コンパイラ設定" tabindex="-1">コンパイラ設定 <a class="header-anchor" href="#コンパイラ設定" aria-label="Permalink to &quot;コンパイラ設定&quot;">​</a></h2><h3 id="gametype-author" tabindex="-1">Gametype Author <a class="header-anchor" href="#gametype-author" aria-label="Permalink to &quot;Gametype Author&quot;">​</a></h3><p>コンパイル済みゲームタイプのメタデータに書き込まれる作成者名です。</p><table tabindex="0"><thead><tr><th>項目</th><th>値</th></tr></thead><tbody><tr><td>最大長</td><td>16 文字</td></tr><tr><td>デフォルト</td><td>空</td></tr></tbody></table><p>ファイルに作者を刻印したくない場合は空のままにしてください。Discord や OS のアカウント名とは別です。</p><h3 id="compiler-profile" tabindex="-1">Compiler profile <a class="header-anchor" href="#compiler-profile" aria-label="Permalink to &quot;Compiler profile&quot;">​</a></h3><p>コンパイラと言語サービスが許可する言語拡張を制御します。</p><table tabindex="0"><thead><tr><th>プロファイル</th><th>動作</th></tr></thead><tbody><tr><td><strong>MegaloEvolved</strong>（デフォルト）</td><td>標準 Megalo の上に MegaloEvolved 製品拡張を有効化</td></tr><tr><td><strong>MegaloEdit</strong></td><td>標準の MegaloEdit に合わせる — MegaloEvolved 専用の言語拡張は無効</td></tr></tbody></table><p>HREK の MegaloEdit コンパイラに近いスクリプト／ツール挙動が必要なときは <strong>MegaloEdit</strong> を使ってください。</p><h3 id="strict-compiler" tabindex="-1">Strict compiler <a class="header-anchor" href="#strict-compiler" aria-label="Permalink to &quot;Strict compiler&quot;">​</a></h3><p>有効にすると、コンパイラは <strong>ローカライゼーションを強制</strong>します。</p><ul><li>文字列テーブルのシンボルが期待される場所での引用符付き文字列リテラルは（警告ではなく）<strong>エラー</strong>になる</li><li>欠落した <a href="/MegaloEvolved/beta/docs/ja/language/elements/localized-include"><code>localized_include</code></a> ファイルはより厳しく扱われる（厳密なローカライゼーション規則に合わせる）</li></ul><p>無効（デフォルト）のときは、寛容な MegaloEdit 風コンパイルに近い挙動になります。リテラルは警告になり得て、一部のローカライゼーション欠落は緩く扱われます。</p><p>Megalo コンパイラのスイッチモデル全体（一時オーバーフローや HREK 背景を含む）は、言語ドキュメントの <a href="/MegaloEvolved/beta/docs/ja/language/compiler-settings">コンパイラ設定</a> を参照してください。IDE のトグルは、そのモデルのうちローカライゼーション／文字列リテラルの厳密さ側に対応します。</p><h2 id="エディタ設定" tabindex="-1">エディタ設定 <a class="header-anchor" href="#エディタ設定" aria-label="Permalink to &quot;エディタ設定&quot;">​</a></h2><h3 id="language" tabindex="-1">Language <a class="header-anchor" href="#language" aria-label="Permalink to &quot;Language&quot;">​</a></h3><p>IDE の UI、診断、ホバーヘルプの言語です。</p><table tabindex="0"><thead><tr><th>値</th><th>意味</th></tr></thead><tbody><tr><td><strong>English</strong></td><td>デフォルトの UI とメッセージ</td></tr><tr><td><strong>日本語</strong></td><td>日本語の UI およびコンパイラ／IDE メッセージ</td></tr></tbody></table><p>コンパイル済みゲームタイプの名前と説明をサイドバーに表示するとき、優先する文字列テーブル言語にも影響します。</p><h3 id="editor-theme" tabindex="-1">Editor theme <a class="header-anchor" href="#editor-theme" aria-label="Permalink to &quot;Editor theme&quot;">​</a></h3><p>Megalo（Monaco）エディタ専用のカラーテーマです。IDE のその他の UI には適用されません。</p><p>利用可能なテーマには、MegaloEvolved Dark、VS Dark、Clouds Midnight、Cobalt2、Dracula、GitHub Dark / Light、Monokai、Night Owl、Nord、Oceanic Next、Solarized Dark / Light、Tomorrow Night、Twilight があります。</p><h3 id="discord-rich-presence" tabindex="-1">Discord rich presence <a class="header-anchor" href="#discord-rich-presence" aria-label="Permalink to &quot;Discord rich presence&quot;">​</a></h3><p>有効にすると、Discord に MegaloEvolved で編集中であること（例: 現在のファイル）を表示できます。編集アクティビティを Discord に共有したくない場合はオフにしてください。</p><table tabindex="0"><thead><tr><th>デフォルト</th><th>オン</th></tr></thead></table><h2 id="関連" tabindex="-1">関連 <a class="header-anchor" href="#関連" aria-label="Permalink to &quot;関連&quot;">​</a></h2><ul><li><a href="/MegaloEvolved/beta/docs/ja/megacrow/workspaces">ワークスペース</a> — スクリプトと出力フォルダ（デスクトップ）</li><li><a href="/MegaloEvolved/beta/docs/ja/megacrow/export">エクスポート</a> — コンパイル出力形式</li><li><a href="/MegaloEvolved/beta/docs/ja/language/compiler-settings">言語のコンパイラ設定</a> — MegaloCompile スイッチの詳細</li></ul>',29)])])}const m=e(l,[["render",i]]);export{p as __pageData,m as default};
